-- =============================================================================
-- Step 30: flatten each raw EDGAR table (annual 10-K facts only)
-- Generated by data/generate-sql.ts. Do not edit by hand; edit data/lib/sqlgen.ts and regenerate.
-- STATUS: UNVERIFIED against a live Zetaris instance (written while the instance was not running).
-- Run with: npx tsx data/run-onboarding.ts [--apply]   (dry-run by default; one statement per call)
-- Rules (mirrored in data/lib/normalize.ts for the fixtures): form 10-K, fp FY, duration 350-380 days (flow
-- concepts) or no start date (instant concepts); fiscal_year = YEAR(period_end - 45 days).
-- =============================================================================

-- WMT revenue from us-gaap:Revenues
CREATE SCHEMASTORE VIEW walmart_revenues_stage WITH CONTAINER edgar_stage AS
SELECT
    'WMT' AS ticker,
    CAST(cik AS BIGINT) AS cik,
    `entityName` AS entity_name,
    'revenue' AS concept,
    tag AS xbrl_tag,
    0 AS tag_priority,
    year(date_sub(to_date(fact.`end`), 45)) AS fiscal_year,
    fact.`start` AS period_start,
    fact.`end` AS period_end,
    CAST(fact.val AS DOUBLE) AS value_usd,
    fact.form AS form_type,
    fact.filed AS filed_date,
    fact.accn AS accession_number
FROM sec_data.walmart_revenues_facts
LATERAL VIEW explode(units.USD) AS fact
WHERE fact.form = '10-K' AND fact.fp = 'FY' AND fact.`start` IS NOT NULL AND datediff(to_date(fact.`end`), to_date(fact.`start`)) BETWEEN 350 AND 380;

